from collections import Counter
A=[[0,4,0,8,0,1],[0,3,0,1,0,0],[6,0,0,0,0,0],[6,0,4,0,8,0],[0,9,0,0,8,8],[8,0,0,3,9,9]]
B=[[0,4,0,8,0,1,8,0,6,6,0,0],[0,3,0,1,0,0,0,9,0,0,3,4],[6,0,0,0,0,0,0,0,4,0,0,0],[6,0,4,0,8,0,3,0,0,0,1,8],[0,9,0,0,8,8,9,8,8,0,0,0],[8,0,0,3,9,9,9,8,0,0,0,1],[1,0,0,0,8,9,9,9,3,0,0,8],[0,0,0,8,8,9,8,8,0,0,9,0],[8,1,0,0,0,3,0,8,0,4,0,6],[0,0,0,4,0,0,0,0,0,0,0,6],[4,3,0,0,9,0,0,0,1,0,3,0],[0,0,6,6,0,8,1,0,8,0,4,0]]
n=6
qs={'TL':[r[:n] for r in B[:n]],'TR':[r[n:] for r in B[:n]],'BL':[r[:n] for r in B[n:]],'BR':[r[n:] for r in B[n:]]}
for k,q in qs.items():
 print(k,'matches input?',q==A, 'counts',Counter(x for r in q for x in r))
print('input counts',Counter(x for r in A for x in r))
# compare arrays under dihedral transformations
import numpy as np
x=np.array(A)
for k,q in qs.items():
 print(k)
 for rot in range(4):
  y=np.rot90(x,rot)
  for flip in [False,True]:
   z=np.fliplr(y) if flip else y
   if np.array_equal(np.array(q),z): print('sym',rot,flip)
# frequency of values across whole output vs source
print('whole counts',Counter(v for r in B for v in r))
